  # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n','5bd89139eb032142eccc77db021eabea','2026-06-08 00:43:22','2026-06-08 00:43:22',NULL,'127.0.0.1','','spaiconfig','系统模块',NULL,NULL,'yaml',NULL,''),(27,'sentinel-ruoyi-gateway','DEFAULT_GROUP','[\r\n    {\r\n        \"resource\": \"ruoyi-auth\",\r\n        \"count\": 500,\r\n        \"grade\": 1,\r\n        \"limitApp\": \"default\",\r\n        \"strategy\": 0,\r\n        \"controlBehavior\": 0\r\n    },\r\n	{\r\n        \"resource\": \"ruoyi-system\",\r\n        \"count\": 1000,\r\n        \"grade\": 1,\r\n        \"limitApp\": \"default\",\r\n        \"strategy\": 0,\r\n        \"controlBehavior\": 0\r\n    },\r\n	{\r\n        \"resource\": \"ruoyi-gen\",\r\n        \"count\": 200,\r\n        \"grade\": 1,\r\n        \"limitApp\": \"default\",\r\n        \"strategy\": 0,\r\n        \"controlBehavior\": 0\r\n    },\r\n	{\r\n        \"resource\": \"ruoyi-job\",\r\n        \"count\": 300,\r\n        \"grade\": 1,\r\n        \"limitApp\": \"default\",\r\n        \"strategy\": 0,\r\n        \"controlBehavior\": 0\r\n    }\r\n]','9f3a3069261598f74220bc47958ec252','2026-06-08 00:43:22','2026-06-08 00:43:22',NULL,'127.0.0.1','','spaiconfig','限流策略',NULL,NULL,'json',NULL,''),(28,'ruoyi-sp-ai-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  servlet:\n    multipart:\n      max-file-size: 100MB\n      max-request-size: 100MB\n  wvp:\n    ipAddress: http://192.168.1.58:18080\n    getdevicesUrl: /api/device/query/devices\n    getChannelsUrl: /api/device/query/devices/{deviceId}/channels\n\n    customTreeChannelAddUrl: /api/customTreeChannel/add\n    customTreeChannelListUrl: /api/customTreeChannel/list\n    customTreeChannelUpdateUrl: /api/customTreeChannel/update\n    customTreeChannelDeleteUrl: /api/customTreeChannel/delete\n    customTreeChannelOtherChanneUrl: /api/customTreeChannel/getOtherChanne\n    customTreeChannelBdChanneUrl: /api/customTreeChannel/getBdChanne\n\n    customTreeSAddUrl: /api/customTreeS/add\n    customTreeSListUrl: /api/customTreeS/list\n    customTreeSUpdateUrl: /api/customTreeS/update\n    customTreeSDeleteUrl: /api/customTreeS/delete\n  hy:\n    ipAddress: http://192.168.1.61:8000\n    #模型\n    modelsListUrl: /models\n    delmodelsByIdUrl: /models/{id}\n    uploadmodelsUrl: /models/upload\n    updatemodelsUrl: /models/{id}\n    othermodelsListUrl: /tasks/{taskId}/available-models?prefer_metadata=true\n\n    #通道\n    channelsSyncUrl: /channels/sync-wvp\n    channelsListUrl: /channels\n    delchannelsUrl: /channels/{id}\n    availableForTaskUrl: /channels/available-for-task\n\n\n    #任务\n    createtaskUrl: /tasks\n    tasksListUrl: /tasks?prefer_metadata=false\n    delTaskByIdUrl: /tasks/{taskId}\n    starttaskUrl: /tasks/{taskId}/start\n    stoptaskUrl: /tasks/{taskId}/stop\n    algorithmsListUrl: /tasks/{taskId}/algorithms?prefer_metadata=false\n    algorithmsBdListUrl: /tasks/{taskId}/algorithms?prefer_metadata=false\n    createalgorithmsUrl: /tasks/{taskId}/algorithms\n    updatealgorithmIdUrl: /tasks/{taskId}/algorithms/{algorithmsId}\n    delalgorithmIdUrl: /tasks/{taskId}/algorithms/{algorithmsId}\n    updateregionsUrl: tasks/{taskId}/regions/{regionsId}\n    snapshotUrl: /channels/{streamId}/snapshot\n    regionsListUrl: /tasks/{taskId}/algorithms/{algorithmsId}/regions\n    saveregionsUrl: /tasks/{taskId}/algorithms/{algorithmsId}/regions\n    #startUrl: /channels/{stream}/zone-preview/start\n    startUrl: /channels/{channel_id}/fence/browser-play-url\n    resourcesUrl: /server/resources\n\n\n  zlm:\n    addStreamProxyUrl: http://192.168.1.61:8008/index/api/addStreamProxy\n    delStreamProxyUrl: http://192.168.1.61:8008/index/api/delStreamProxy\n    isMediaOnlineUrl: http://192.168.1.61:8008/index/api/isMediaOnline\n    secret: KRxIqCpZxqXE3c7F9fMOqWssKGj6hkdO\n  # 和风天气\n  weather:\n    privateKey: MC4CAQAwBQYDK2VwBCIEIBmYMH1sIPMWfVcgYxrJsnFfxCoJCQ4r16J58UMfTZFo\n    # 凭据ID\n    kid: KMWDYA7YM9\n    # 项目ID\n    sub: 38E4MRXNYC\n    # 