l://192.168.1.200:3307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            url: jdbc:mysql://192.168.1.200:3307/jove-warning2?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            # url: jdbc:mysql://499g002n71.zicp.vip:53307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            username: root\r\n            password: root\r\n          #slave:\r\n            #driver-class-name: com.mysql.cj.jdbc.Driver\r\n            ## url: jdbc:mysql://192.168.1.200:3307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            #url: jdbc:mysql://192.168.1.200:3307/jove-warning2?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            ## url: jdbc:mysql://499g002n71.zicp.vip:53307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\r\n            #username: root\r\n            #password: root\r\n          slave:\r\n            driver-class-name: com.taosdata.jdbc.rs.RestfulDriver\r\n            url: jdbc:TAOS-RS://192.168.1.36:6041/warning\r\n            username: root\r\n            password: taosdata\r\n            connection-properties:\r\n              charset: UTF-8\r\n              timezone: Asia/Shanghai\r\n\r\n# seata配置\r\nseata:\r\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\r\n  enabled: false\r\n  # Seata 应用编号，默认为 ${spring.application.name}\r\n  application-id: ${spring.application.name}\r\n  # Seata 事务组编号，用于 TC 集群名\r\n  tx-service-group: ${spring.application.name}-group\r\n  # 关闭自动代理\r\n  enable-auto-data-source-proxy: false\r\n  # 服务配置项\r\n  service:\r\n    # 虚拟组和分组的映射\r\n    vgroup-mapping:\r\n      jove-system-prod-group: default\r\n  config:\r\n    type: nacos\r\n    nacos:\r\n      serverAddr: xxx.xx.xx.xx:6001\r\n      group: SEATA_GROUP\r\n      namespace:\r\n  registry:\r\n    type: nacos\r\n    nacos:\r\n      application: seata-server\r\n      server-addr: xx.xx.x.xxx:6001\r\n      namespace:\r\n\r\n# mybatis配置\r\nmybatis:\r\n  configuration: \r\n    # 超时单位为秒\r\n    default-statement-timeout: 900\r\n  # 搜索指定包别名\r\n  typeAliasesPackage: com.jovefast.warning\r\n  # 配置mapper的扫描，找到所有的mapper.xml映射文件\r\n  mapperLocations: classpath:mapper/**/*.xml\r\n\r\nmybatis-plus:\r\n  mapper-locations: classpath*:mapper/**/*.xml\r\n  type-aliases-package: com.jovefast.warning\r\n  configuration:\r\n    map-underscore-to-camel-case: true\r\n\r\n# swagger配置\r\nswagger:\r\n  title: 系统模块接口文档\r\n  license: Powered By xxx\r\n  licenseUrl: https://xxx.com\r\n  enabled: false   \r\n# 暴露监控端点\r\nmanagement:\r\n  endpoints:\r\n    web:\r\n      exposure:\r\n        include: \'*\'\r\n  endpoint:\r\n    health:\r\n      show-details: ALWAYS\r\n    logfile:\r\n      #可在线查看日志\r\n      enabled: true\r\n      external-file: logs/jove-warning.log\r\n\r\n# 配置debug模式sql输出\r\nlogging:\r\n  level:  \r\n    com.jovefast: debug\r\n    org.springframework: warn\r\n# application.yml 格式\r\nmaxkb:\r\n  base-url: http://192.168.1.61:8081/  # MaxKB服务地址http://10rg9383km827.vicp.fun:8888\r\n  app-id: bf734cb162785ef1           # 从MaxKB后台获取\r\n  token5: application-41565b89a3ff7e131c97d7245351786c            #测试语音交互\r\n  username: admin\r\n  password: Hy34563456.\r\n  tzdz: http://192.168.1.61:8081/','97690b6cc9deb338abb9d7d29001cc86','2026-06-23 06:35:12','2026-06-23 06:35:12',NULL,'127.0.0.1','','',NULL,NULL,NULL,'yaml',NULL,''),(78,'application-dev.yml','DEFAULT_GROUP','spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n','9928f41dfb10386ad38b3254af5692e0','2026-06-24 03:55:30','2026-06-24 03:55:30',NULL,'127.0.0.1','','hzktdconfig',NULL,NULL,NULL,'yaml',NULL,''),(79,'ruoyi-gateway-dev.yml','DEFAULT_GROUP','spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: ruoyi-auth\n          uri: lb://ruoyi-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestBody\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: ruoyi-gen\n          uri: lb://ruoyi-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: ruoyi-job\n          uri: lb://ruoyi-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: ruoyi-system\n          uri: lb://ruoyi-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: ruoyi-file\n          uri: lb://ruoyi-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n                  # 系统模块\n        - id: ruoyi-ktds\n          uri: lb://ruoyi-ktds\n          predicates:\n            - Path=/ktd/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n','0912d47b1845da4b4cc46a68c3b56e2d','2026-06-24 03:55:30','2026-06-24 03:55:30',NULL,'127.0.0.1','','hzktdconfig',NULL,NULL,NULL,'yaml',NULL,''),(80,'ruoyi-auth-dev.yml','DEFAULT_GROUP','spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n','a03e7632a0a74520eeb4fbedd6d82d97','2026-06-24 03:55:30','2026-06-24 03:55:30',NULL,'127.0.0.1','','hzktdconfig',NULL,NULL,NULL,'yaml',NULL,''),(81,'ruoyi-monitor-dev.yml','DEFAULT_GROUP','# spring\nspring:\n  security:\n    user:\n      name: ruoyi\n      password: 123456\n  boot:\n    admin:\n      ui:\n        title: 若依服务状态监控\n','6f122fd2bfb8d45f858e7d6529a9cd44','2026-06-24 03:55:30','2026-06-24 03:55:30',NULL,'127.0.0.1','','hzktdconfig',NULL,NULL,NULL,'yaml',NULL,''),(82,'ruoyi-system-dev.yml','DEFAULT_GROUP','# spring配置\nspring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://19