oud/unzippath\n  geoserver:\n    geoserverUrl: http://192.168.1.200:9100/geoserver \n  redis:\n    lettuce:\n      shutdown-timeout: 100\n    host: 127.0.0.1\n    port: 6379\n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: admin\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 300000\n        timeBetweenEvictionRunsMillis: 300000\n        minEvictableIdleTimeMillis: 300000\n        maxEvictableIdleTimeMillis: 600000\n        idleConnectionTestPeriod: 120\n        testConnectionOnCheckout: false\n        testConnectionOnCheckin: true\n        validationQuery: SELECT 1\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        usePingMethod: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            # url: jdbc:mysql://192.168.1.200:3307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            url: jdbc:mysql://192.168.1.200:3307/jove-warning2?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            # url: jdbc:mysql://499g002n71.zicp.vip:53307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: root\n          slave:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            # url: jdbc:mysql://192.168.1.200:3307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            url: jdbc:mysql://192.168.1.200:3307/jove-warning2?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            # url: jdbc:mysql://499g002n71.zicp.vip:53307/jove-warning?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: root\n          #slave:\n          #  driver-class-name: com.taosdata.jdbc.rs.RestfulDriver\n          #  url: jdbc:TAOS-RS://192.168.1.36:6041/warning\n          #  username: root\n          #  password: taosdata\n          #  connection-properties:\n          #    charset: UTF-8\n          #    timezone: Asia/Shanghai\n\n# seata配置\nseata:\n  # 默认关闭，如需启用spring.datasource.dynami.seata需要同时开启\n  enabled: false\n  # Seata 应用编号，默认为 ${spring.application.name}\n  application-id: ${spring.application.name}\n  # Seata 事务组编号，用于 TC 集群名\n  tx-service-group: ${spring.application.name}-group\n  # 关闭自动代理\n  enable-auto-data-source-proxy: false\n  # 服务配置项\n  service:\n    # 虚拟组和分组的映射\n    vgroup-mapping:\n      jove-system-prod-group: default\n  config:\n    type: nacos\n    nacos:\n      serverAddr: xxx.xx.xx.xx:6001\n      group: SEATA_GROUP\n      namespace:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: xx.xx.x.xxx:6001\n      namespace:\n\n# mybatis配置\nmybatis:\n  configuration: \n    # 超时单位为秒\n    default-statement-timeout: 900\n  # 搜索指定包别名\n  typeAliasesPackage: com.jovefast.warning\n  # 配置mapper的扫描，找到所有的mapper.xml映射文件\n  mapperLocations: classpath:mapper/**/*.xml\n\nmybatis-plus:\n  mapper-locations: classpath*:mapper/**/*.xml\n  type-aliases-package: com.jovefast.warning\n  configuration:\n    map-underscore-to-camel-case: true\n\n# swagger配置\nswagger:\n  title: 系统模块接口文档\n  license: Powered By xxx\n  licenseUrl: https://xxx.com\n  enabled: false   \n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n  endpoint:\n    health:\n      show-details: ALWAYS\n    logfile:\n      #可在线查看日志\n      enabled: true\n      external-file: logs/jove-warning.log\n\n# 配置debug模式sql输出\nlogging:\n  level:  \n    com.jovefast: debug\n    org.springframework: warn\n# application.yml 格式\nmaxkb:\n  base-url: http://192.168.1.61:8081/  # MaxKB服务地址http://10rg9383km827.vicp.fun:8888\n  app-id: bf734cb162785ef1           # 从MaxKB后台获取\n  token5: application-41565b89a3ff7e131c97d7245351786c            #测试语音交互\n  username: admin\n  password: Hy34563456.\n  tzdz: http://192.168.1.61:8081/','00b6021b6b18dcbf1d53adb8071fcc57','2026-06-04 17:19:59','2026-06-04 09:22:52',NULL,'127.0.0.1','D','','','formal',NULL,NULL),(2,89,'ruoyi-gateway-dev.yml','DEFAULT_GROUP','','spring:\n  redis:\n    host: localhost\n    port: 6379\n    password: \n  cloud:\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: ruoyi-auth\n          uri: lb://ruoyi-auth\n          predicates:\n            - Path=/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestBody\n            - ValidateCodeFilter\n            - StripPrefix=1\n        # 代码生成\n        - id: ruoyi-gen\n          uri: lb://ruoyi-gen\n          predicates:\n            - Path=/code/**\n          filters:\n            - StripPrefix=1\n        # 定时任务\n        - id: ruoyi-job\n          uri: lb://ruoyi-job\n          predicates:\n            - Path=/schedule/**\n          filters:\n            - StripPrefix=1\n        # 系统模块\n        - id: ruoyi-system\n          uri: lb://ruoyi-system\n          predicates:\n            - Path=/system/**\n          filters:\n            - StripPrefix=1\n        # 文件服务\n        - id: ruoyi-file\n          uri: lb://ruoyi-file\n          predicates:\n            - Path=/file/**\n          filters:\n            - StripPrefix=1\n                  # 系统模块\n        - id: ruoyi-ktds\n          uri: lb://ruoyi-ktds\n          predicates:\n            - Path=/ktd/**\n          filters:\n            - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n','0912d47b1845da4b4cc46a68c3b56e2d','2026-06-04 17:23:16','2026-06-04 09:26:10',NULL,'127.0.0.1','U','','','formal',NULL,NULL),(22,90,'ruoyi-sp-ai-dev','DEFAULT_GROUP','','# spring配置\r\nspring:\r\n  zlm:\r\n    addStreamProxyUrl: http://192.168.1.61:8008/index/api/addStreamProxy\r\n    delStreamProxyUrl: http://192.168.1.61:8008/index/api/delStreamProxy\r\n    isMediaOnlineUrl: http://192.168.1.61:8008/index/api/isMediaOnline\r\n    secret: KRxIqCpZxqXE3c7F9fMOqWssKGj6hkdO\r\n  # 和风天气\r\n  weather:\r\n    privateKey: MC4CAQAwBQYDK2VwBCIEIBmYMH1sIPMWfVcgYxrJsnFfxCoJCQ4r16J58UMfTZFo\r\n    # 凭据ID\r\n    kid: KMWDYA7YM9\r\n    # 项目ID\r\n    sub: 38E4MRXNYC\r\n    # 城市地址编号\r\n    location: 101010100\r\n    locationname: 北京市\r\n    nowUrl: https://mf5pwe843w.re.qweatherapi.com/v7/weather/now\r\n    7dUrl: https://mf5pwe843w.re.qweatherapi.com/v7/weather/7d\r\n  redis:\r\n    host: localhost\r\n    port: 6379\r\n    password: \r\n  datasource:\r\n    druid:\r\n      stat-view-servlet:\r\n        enabled: true\r\n        loginUsername: ruoyi\r\n        loginPassword: 123456\r\n    dynamic:\r\n      druid:\r\n        initial-size: 5\r\n        min-idle: 5\r\n        maxActive: 20\r\n        maxWait: 60000\r\n        connectTimeout: 30000\r\n        socketTimeout: 60000\r\n        timeBetweenEvictionRunsMillis: 60000\r\n        minEvictableIdleTimeMillis: 300000\r\n        validationQuery: SELECT 1 FROM DUAL\r\n        testWhileIdle: true\r\n        testOnBorrow: false\r\n       